sources.programPatch:
--- 

+++ 

@@ -971,7 +971,7 @@

         report.AppendLine("Actions: workspace navigation, Media preview segment, selected details/inspector, scroll offset changes, synthetic task search text updates, Light/Dark theme");
         report.AppendLine("Input boundary: TaskSearchTextBox.Text is changed programmatically against FakeDashboardData; this is a logical WPF update/layout proxy, not physical keyboard, IME, or presented-frame latency");
         report.AppendLine("Resources: GC.GetTotalMemory(false), PrivateMemorySize64, WorkingSet64, handles, timers, managed event handlers, animated owners and thumbnail cache; no forced GC in this probe");
-        report.AppendLine($"DurationTargetSeconds: {durationSeconds}");
+        report.AppendLine($"FixedCycleTarget: 70; SafetyTimeoutSeconds: {durationSeconds}");
         report.AppendLine($"PostActionSettleSeconds: {postActionSettleSeconds}");
         AppendRunMetadata(
             report,
@@ -1236,6 +1236,7 @@

             window.Show();
             window.UpdateLayout();
             LayoutCurrentPage(pages[0].View, ThemeModes[0].Mode);
+            U09Performance.Begin();
             RecordSample(final: false);

             actionTimer = new DispatcherTimer(DispatcherPriority.Background, window.Dispatcher)
@@ -1254,10 +1255,11 @@

                     lastProgressAt = elapsed;
                 }

-                if (elapsed >= TimeSpan.FromSeconds(durationSeconds))
+                if (cycle >= 70 || elapsed >= TimeSpan.FromSeconds(durationSeconds))
                 {
                     actionTimer!.Stop();
                     actionStoppedAt = elapsed;
+                    U09Performance.Stop(cycle, completedActions);
                     settleTimer = new DispatcherTimer(DispatcherPriority.Background, window.Dispatcher)
                     {
                         Interval = TimeSpan.FromSeconds(1)
@@ -1283,6 +1285,8 @@

             actionTimer.Start();
             app.Run();
             stopwatch.Stop();
+            U09Performance.End(outputRoot);
+            if (cycle != 70) problems.Add("Fixed-cycle diagnostic did not complete exactly 70 cycles");

             if (samples.Count < 2)
                 problems.Add($"only {samples.Count} resource samples were recorded");
@@ -1300,7 +1304,7 @@

                 cycle,
                 completedActions,
                 actionFailureCount,
-                durationSeconds + postActionSettleSeconds);
+                (int)Math.Ceiling(stopwatch.Elapsed.TotalSeconds));
             report.AppendLine(problems.Count == 0 ? "enduranceprobe OK" : "enduranceprobe FAILED");
             foreach (var problem in problems)
                 report.AppendLine("  PROBLEM " + problem);

